//! Regenerates `src/generated.rs` from the schema and fails if the checked-in
//! copy differs. Run with `UPDATE_PROTO=1` to rewrite the file instead.

use std::path::PathBuf;
use typify::{TypeSpace, TypeSpaceSettings};

const HEADER: &str = "\
// @generated by `UPDATE_PROTO=1 cargo test -p easyssh-proto --test codegen`.
// Source: schema/proto.schema.json. Do not edit by hand.
#![allow(clippy::all, unused_imports, dead_code)]

";

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn generate() -> String {
    let schema = std::fs::read_to_string(crate_dir().join("schema/proto.schema.json")).unwrap();
    // typify 0.10 reads schemars 0.8 documents, which spell `$defs` as
    // `definitions`. The checked-in schema keeps the 2020-12 spelling.
    let schema = schema
        .replace("\"$defs\"", "\"definitions\"")
        .replace("#/$defs/", "#/definitions/");
    let root: schemars::schema::RootSchema = serde_json::from_str(&schema).unwrap();
    let mut space = TypeSpace::new(&TypeSpaceSettings::default());
    space.add_root_schema(root).unwrap();
    let file = syn::parse2::<syn::File>(space.to_stream().unwrap()).unwrap();
    format!("{HEADER}{}", prettyplease::unparse(&file))
}

#[test]
fn generated_types_are_up_to_date() {
    let path = crate_dir().join("src/generated.rs");
    let expected = generate();
    if std::env::var_os("UPDATE_PROTO").is_some() {
        std::fs::write(&path, expected).unwrap();
        return;
    }
    let actual = std::fs::read_to_string(&path).unwrap_or_default();
    assert!(
        actual == expected,
        "src/generated.rs is stale; run `UPDATE_PROTO=1 cargo test -p easyssh-proto --test codegen`"
    );
}
